const crypto = require('crypto');
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const secret = $env.AUTOMATION_WEBHOOK_SECRET || '';
const item = $input.all()[0].json;
const headers = item.headers || {};
const body = item.body || {};
const envelope = { eventId: body.eventId, name: body.name, businessId: body.businessId, occurredAt: body.occurredAt, data: body.data };
const rawBody = JSON.stringify(envelope);
const ts = Number(headers['x-automation-timestamp']);
const sig = String(headers['x-automation-signature'] || '');
let validSig = false;
try {
  const expected = crypto.createHmac('sha256', secret).update(`${ts}.${rawBody}`).digest('hex');
  const a = Buffer.from(expected, 'hex');
  const b = Buffer.from(sig, 'hex');
  validSig = a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (e) { validSig = false; }
const fresh = Number.isFinite(ts) && Math.abs(Date.now() - ts) < 5 * 60 * 1000;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const duplicate = !!store.seen[body.eventId];
let route;
if (!secret || !validSig || !fresh) route = 'auth_failed';
else if (duplicate) route = 'duplicate';
else { store.seen[body.eventId] = Date.now(); route = body.name; }

// Helpers de presentacion: branding por cliente + fecha legible.
const d = body.data || {};
const br = d.branding || {};
const primary = br.primary || '#4f46e5';
const secondary = br.secondary || primary;
// Logo del negocio: el back sirve el logo real (GET /public/business/:id/logo) como
// imagen — Gmail no muestra data:base64, pero sí una URL http. Sin logo → PNG transparente.
const CRM_URL = ($env.CRM_PUBLIC_URL || 'https://crm-back-ul2b.onrender.com').replace(/\/$/, '');
const logoHtml = `<img src="${CRM_URL}/public/business/${esc(String(body.businessId || ''))}/logo" alt="${esc(d.businessName || '')}" height="80" style="height:80px;max-width:320px;border-radius:10px;object-fit:contain"/>`;
let expiresHuman = d.expiresAt || '';
try {
  const dt = new Date(d.expiresAt);
  if (!isNaN(dt.getTime())) {
    const p = (n) => String(n).padStart(2, '0');
    expiresHuman = `${p(dt.getDate())}/${p(dt.getMonth() + 1)}/${dt.getFullYear()} ${p(dt.getHours())}:${p(dt.getMinutes())}`;
  }
} catch (e) {}

// Guard anti-bounce: nunca enviar a dominios reservados de test (.test/.local/example.*).
// Evita rebotes del subsistema de correo cuando las suites e2e usan emails falsos.
const __email = String((body.data || {}).email || '');
if (!['auth_failed', 'duplicate'].includes(route) && /(\.test|\.local|@example\.(com|net|org))$/i.test(__email)) route = 'skip';

// XSS guard: expose an HTML-escaped mirror of every string field so email
// templates interpolate data.safe.* instead of raw attacker-controlled values.
const safe = {};
for (const k of Object.keys(d)) { if (typeof d[k] === 'string') safe[k] = esc(d[k]); }
d.safe = safe;

return [{ json: { route, eventId: body.eventId, businessId: body.businessId, name: body.name, data: d, primary, secondary, logoHtml, expiresHuman } }];
